import six
from abc import ABCMeta, abstractmethod
from taf.ue.plugin.mtk.commands import EFUN
from taf.ue.plugin.mtk.flow.action_verifiable import ActionSequenceVerifiable


@six.add_metaclass(ABCMeta)
class Attach(ActionSequenceVerifiable):

    @abstractmethod
    def __init__(self, executor=None, verifier=None):
        self._executor = executor
        self._verifier = verifier

    def _generate_command_sequence(self):
        return [EFUN(self._executor, EFUN.Status.ENABLE)]

    def verify(self):
        if self._verifier:
            self._verifier.verify()


class NSAAttach(Attach):

    def __init__(self, executor=None, verifier=None):
        super(NSAAttach, self).__init__(executor=executor, verifier=verifier)


class SAAttach(Attach):

    def __init__(self, executor=None, verifier=None):
        super(SAAttach, self).__init__(executor=executor, verifier=verifier)


class LTEAttach(Attach):

    def __init__(self, executor=None, verifier=None):
        super(LTEAttach, self).__init__(executor=executor, verifier=verifier)
